test('filterNames with empty query returns all names', () => {
  const names = ['Alice Johnson', 'Boris Petrov'];
  assert.deepStrictEqual(filterNames(names, ''), names);
});

test('filterNames with whitespace-only query returns all names', () => {
  const names = ['Alice Johnson', 'Boris Petrov'];
  assert.deepStrictEqual(filterNames(names, '   '), names);
});

test('filterNames matches case-insensitively', () => {
  const names = ['Alice Johnson', 'Boris Petrov', 'Carol Nguyen'];
  assert.deepStrictEqual(filterNames(names, 'ALICE'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(names, 'boris'), ['Boris Petrov']);
});

