  const names = ['Alice Johnson', 'Boris Petrov'];
  assert.deepStrictEqual(filterNames(names, 'zzz'), []);
});

test('filterNames does not mutate the input array', () => {
  const names = ['Alice Johnson', 'Boris Petrov'];
  const copy = [...names];
  filterNames(names, 'alice');
  assert.deepStrictEqual(names, copy);
});

